104:         action: ActionId,
105:     ) -> Result<&'a ActionPack, ExecutorError> {
106:         let ArtifactEvidence::Packed(packed) = &artifact.verification.evidence else {
107:             return Err(ExecutorError::CatalogRequired);
108:         };
109:         let index = packed
110:             .packs
111:             .binary_search_by_key(&action, |pack| pack.action)
112:             .map_err(|_| ExecutorError::PackMismatch)?;
113:         packed.packs.get(index).ok_or(ExecutorError::PackMismatch)
