5: impl<'j> JournalWriteBatch<'j> {
6:     /// Sets strict durability for the commit.
7:     pub fn strict(mut self) -> Self {
8:         self.inner = self.inner.durability(Some(fjall::PersistMode::SyncAll));
9:         self
